import{_ as o,r as n,o as l,c as p,e as a,a as d,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Data Table Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Data Table"},"headers":[{"level":4,"title":"Column Configuration","slug":"column-configuration","link":"#column-configuration","children":[]},{"level":4,"title":"Column Types","slug":"column-types","link":"#column-types","children":[]},{"level":4,"title":"Dropdown and Autocomplete Options","slug":"dropdown-and-autocomplete-options","link":"#dropdown-and-autocomplete-options","children":[]},{"level":4,"title":"Column Dependencies","slug":"column-dependencies","link":"#column-dependencies","children":[]},{"level":4,"title":"Column Validation","slug":"column-validation","link":"#column-validation","children":[]}],"relativePath":"4.x/element/form/widget-datatable.md","filePath":"4.x/element/form/widget-datatable.md"}'),c={name:"4.x/element/form/widget-datatable.md"};function i(u,t,k,g,h,m){const e=n("pre-heading"),s=n("post-heading");return l(),p("div",null,[a(e),t[0]||(t[0]=d("h1",null,"Data Table Field",-1)),a(s),t[1]||(t[1]=r(`<p><code>datatable</code> - renders an editable table of records, formatted as a grid. Cell content can be editable directly in the grid, allowing for the management of several rows and columns of information.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">data</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datatable
    <span class="token key atrule">adding</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">deleting</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">columns</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    <span class="token key atrule">searching</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>In order to use this with a model, the field should be defined in the <a href="./../../extend/system/models.html">jsonable property</a> or anything that can handle storing as an array.</p></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>adding</strong></td><td>allow records to be added to the data table. Default: <code>true</code>.</td></tr><tr><td><strong>deleting</strong></td><td>allow records to be deleted from the data table. Default: <code>true</code>.</td></tr><tr><td><strong>toolbar</strong></td><td>show the toolbar above the data table. Default: <code>true</code>.</td></tr><tr><td><strong>searching</strong></td><td>allow records to be searched via a search box. Default: <code>false</code>.</td></tr><tr><td><strong>sorting</strong></td><td>allow columns to be sorted by clicking the column header. Default: <code>false</code>.</td></tr><tr><td><strong>reorderRows</strong></td><td>allow rows to be manually reordered by dragging the row handle. Default: <code>false</code>.</td></tr><tr><td><strong>reorderColumns</strong></td><td>allow columns to be manually reordered by dragging the column header. Default: <code>false</code>.</td></tr><tr><td><strong>height</strong></td><td>the data table&#39;s height, in pixels. If set to <code>false</code>, the data table will stretch to fit the content. Default: <code>false</code>.</td></tr><tr><td><strong>placeholder</strong></td><td>a title to display as a placeholder overlay when the table has no rows. When set, the table starts empty (no automatic blank row). Default: <code>false</code>.</td></tr><tr><td><strong>columns</strong></td><td>an array representing the column configuration of the data table. See the <em>Column Configuration</em> section below.</td></tr></tbody></table></div><h4 id="column-configuration"><a href="#column-configuration" class="header-anchor">#</a> Column Configuration</h4><p>The data table widget allows for the specification of columns as an array via the <code>columns</code> configuration variable. Each column should use the field name as a key, and the following configuration variables to set up the field.</p><p>Example:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Name
    <span class="token key atrule">price</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> numeric
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Price
        <span class="token key atrule">width</span><span class="token punctuation">:</span> 100px
    <span class="token key atrule">country</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">state</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">title</span><span class="token punctuation">:</span> State
        <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">is_active</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> checkbox
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Active
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>the input type for this column&#39;s cells. See the <em>Column Types</em> section below.</td></tr><tr><td><strong>title</strong></td><td>defines the column&#39;s title.</td></tr><tr><td><strong>width</strong></td><td>defines the width of the column, in pixels. Example: <code>100px</code>.</td></tr><tr><td><strong>readOnly</strong></td><td>whether this column is read-only. Default: <code>false</code>.</td></tr><tr><td><strong>ellipsis</strong></td><td>truncate overflowing cell content with <code>...</code> instead of clipping silently. Requires a fixed <code>width</code> to take visible effect. Default: <code>false</code>.</td></tr><tr><td><strong>validation</strong></td><td>an array specifying the validation for the content of the column&#39;s cells. See the <em>Column Validation</em> section below.</td></tr><tr><td><strong>options</strong></td><td>for <code>dropdown</code> columns only - specifies the available options as a <code>{key: label}</code> map. The grid stores the <strong>key</strong> in the data and shows the <strong>label</strong> in the cell. If omitted, options will be loaded via AJAX using the model&#39;s <code>getDataTableOptions</code> method.</td></tr><tr><td><strong>dependsOn</strong></td><td>specifies the name of another column that this column depends on. When the parent column value changes, this column&#39;s value is cleared and its options are refreshed.</td></tr><tr><td><strong>dateFormat</strong></td><td>for <code>date</code> columns only - the date format. Default: <code>YYYY-MM-DD</code>.</td></tr><tr><td><strong>timeFormat</strong></td><td>for <code>time</code> columns only - the time format. Default: <code>HH:mm</code>.</td></tr></tbody></table></div><h4 id="column-types"><a href="#column-types" class="header-anchor">#</a> Column Types</h4><p>The following column types are available.</p><div class="table"><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>string</strong></td><td>a standard text input (default).</td></tr><tr><td><strong>checkbox</strong></td><td>a checkbox for boolean values.</td></tr><tr><td><strong>numeric</strong></td><td>a numeric input that only accepts numbers, including decimals.</td></tr><tr><td><strong>dropdown</strong></td><td>a strict dropdown select list. The full list is always shown when opened; the user must pick one of the configured options. Options can be provided inline via the <code>options</code> property, or loaded dynamically via AJAX.</td></tr><tr><td><strong>autocomplete</strong></td><td>a text input with autocomplete suggestions. The list filters as the user types and free-text entry is allowed. Options can be provided inline via the <code>options</code> property, or loaded dynamically via AJAX.</td></tr><tr><td><strong>date</strong></td><td>a date picker input.</td></tr><tr><td><strong>time</strong></td><td>a time picker input.</td></tr></tbody></table></div><h4 id="dropdown-and-autocomplete-options"><a href="#dropdown-and-autocomplete-options" class="header-anchor">#</a> Dropdown and Autocomplete Options</h4><p>Dropdown and autocomplete column options can be provided in two ways.</p><p><strong>Inline options</strong> are defined directly in the column configuration.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">status</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Status
        <span class="token key atrule">options</span><span class="token punctuation">:</span>
            <span class="token key atrule">draft</span><span class="token punctuation">:</span> Draft
            <span class="token key atrule">published</span><span class="token punctuation">:</span> Published
            <span class="token key atrule">archived</span><span class="token punctuation">:</span> Archived
</code></pre></div><p><strong>AJAX options</strong> are loaded dynamically from the model when no inline <code>options</code> are specified. The widget will call one of the following methods on the model.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>get<em>FieldName</em>DataTableOptions</strong></td><td>called first, where <em>FieldName</em> is the studly-cased field name (e.g., <code>getRatesDataTableOptions</code>). Receives <code>$column</code> and <code>$rowData</code> parameters.</td></tr><tr><td><strong>getDataTableOptions</strong></td><td>a generic fallback method. Receives <code>$fieldName</code>, <code>$column</code> and <code>$rowData</code> parameters.</td></tr></tbody></table></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getRatesDataTableOptions</span><span class="token punctuation">(</span><span class="token variable">$column</span><span class="token punctuation">,</span> <span class="token variable">$rowData</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$column</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;au&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Australia&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;United States&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$column</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;state&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Use $rowData[&#39;country&#39;] to return dependent options</span>
        <span class="token keyword">return</span> <span class="token class-name static-context">State</span><span class="token operator">::</span><span class="token function">getNamesByCountry</span><span class="token punctuation">(</span><span class="token variable">$rowData</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="column-dependencies"><a href="#column-dependencies" class="header-anchor">#</a> Column Dependencies</h4><p>A column can depend on another column using the <code>dependsOn</code> property. When the parent column value changes, the dependent column value is automatically cleared and its dropdown options are refreshed.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">country</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">state</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">title</span><span class="token punctuation">:</span> State
        <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
</code></pre></div><h4 id="column-validation"><a href="#column-validation" class="header-anchor">#</a> Column Validation</h4><p>Column cells can be validated against the below types of validation. Validation should be specified as an array within the column configuration.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">id</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> ID
        <span class="token key atrule">validation</span><span class="token punctuation">:</span>
            <span class="token key atrule">integer</span><span class="token punctuation">:</span>
                <span class="token key atrule">message</span><span class="token punctuation">:</span> Please enter a number
            <span class="token key atrule">required</span><span class="token punctuation">:</span>
                <span class="token key atrule">message</span><span class="token punctuation">:</span> This field is required
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>Validation</th><th>Description</th></tr></thead><tbody><tr><td><strong>required</strong></td><td>validates that data must be entered before saving.</td></tr><tr><td><strong>integer</strong></td><td>validates that the data is an integer.</td></tr><tr><td><strong>float</strong></td><td>validates that the data is a floating-point number.</td></tr><tr><td><strong>regex</strong></td><td>validates the data against a regular expression. A string <code>pattern</code> attribute must be provided.</td></tr></tbody></table></div>`,27))])}const b=o(c,[["render",i]]);export{f as __pageData,b as default};
